"use server";

import { z } from "zod";
import { currentUserId } from "@/lib/invitations/access";
import { GUEST_COLUMNS, toOwnGuest, type OwnGuest } from "@/lib/guests/access";
import { GUEST_LIMITS, guestInputSchema, guestName, partySize } from "@/lib/guests/schema";
import { createClient } from "@/lib/supabase/server";

/**
 * The editor's guest list. Every write goes through the couple's own session, so RLS decides
 * whether the invitation or guest is theirs; ids from the client are only ever filters. Tokens are
 * generated by the database (24 random bytes) and never accepted from the client.
 */

const uuid = z.uuid();
const CHECK_VIOLATION = "23514";

export type GuestResult<T> =
  | { ok: true; data: T }
  | { ok: false; reason: "invalid" | "notFound" | "failed" | "belowRsvp"; confirmed?: number };

const addSchema = z.object({
  names: z.array(guestName).min(1).max(GUEST_LIMITS.bulk),
  maxPartySize: partySize,
});

/** Adds one guest or a pasted list, all with the same party-size limit, in the given order. */
export async function addGuests(invitationId: string, input: { names: string[]; maxPartySize: number }): Promise<GuestResult<OwnGuest[]>> {
  const parsed = addSchema.safeParse(input);
  if (!uuid.safeParse(invitationId).success || !parsed.success) return { ok: false, reason: "invalid" };
  if (!(await currentUserId())) return { ok: false, reason: "notFound" };

  const supabase = await createClient();
  const { data, error } = await supabase
    .from("guests")
    .insert(parsed.data.names.map((name) => ({ invitation_id: invitationId, name, max_party_size: parsed.data.maxPartySize })))
    .select(GUEST_COLUMNS)
    .order("created_at")
    .order("id");
  // Someone else's (or a deleted) invitation fails the RLS check on insert.
  if (error) return { ok: false, reason: error.code === "42501" ? "notFound" : "failed" };
  return { ok: true, data: data.map(toOwnGuest) };
}

export async function updateGuest(guestId: string, input: { name: string; maxPartySize: number }): Promise<GuestResult<OwnGuest>> {
  const parsed = guestInputSchema.safeParse(input);
  if (!uuid.safeParse(guestId).success || !parsed.success) return { ok: false, reason: "invalid" };
  if (!(await currentUserId())) return { ok: false, reason: "notFound" };

  const supabase = await createClient();
  const { data, error } = await supabase
    .from("guests")
    .update({ name: parsed.data.name, max_party_size: parsed.data.maxPartySize })
    .eq("id", guestId)
    .select(GUEST_COLUMNS)
    .maybeSingle();
  if (error?.code === CHECK_VIOLATION) {
    // The guest already confirmed more people than the new limit (guests_check_max_party_size).
    const { data: rsvp } = await supabase.from("rsvps").select("party_size").eq("guest_id", guestId).maybeSingle();
    return { ok: false, reason: "belowRsvp", confirmed: rsvp?.party_size };
  }
  if (error) return { ok: false, reason: "failed" };
  if (!data) return { ok: false, reason: "notFound" };
  return { ok: true, data: toOwnGuest(data) };
}

/** Deletes a guest; their RSVP goes with them. */
export async function deleteGuest(guestId: string): Promise<GuestResult<null>> {
  if (!uuid.safeParse(guestId).success) return { ok: false, reason: "invalid" };
  if (!(await currentUserId())) return { ok: false, reason: "notFound" };

  const supabase = await createClient();
  const { data, error } = await supabase.from("guests").delete().eq("id", guestId).select("id");
  if (error) return { ok: false, reason: "failed" };
  if (data.length === 0) return { ok: false, reason: "notFound" };
  return { ok: true, data: null };
}
